pub fn fire_building_base_flammability(kind: &str) -> f64 {
    match kind {
        "founders_camp" => 0.0,
        "remote_work_camp" => 1.55,
        "town_hall" => 0.0,
        "stable" => 1.65,
        "well" => 0.0,
        "marketplace" => 0.0,
        "stone_quarry" => 0.0,
        "large_quarry" => 0.0,
        "mine" => 0.0,
        "chapel" => 0.32,
        "monastery" => 0.32,
        "smokehouse" => 2.2,
        "charcoal_burner" => 2.2,
        "smithy" => 1.8,
        "potter_kiln" => 1.8,
        "clay_pit" => 0.15,
        "brewery" => 1.45,
        "bakery" => 2.0,
        "granary" => 1.45,
        "lumber_mill" => 1.7,
        "woodcutters_lodge" => 1.7,
        "reforester" => 1.7,
        "carpenter" => 1.7,
        "threshing_barn" => 1.65,
        "apiary" => 1.25,
        "fishing_camp" => 1.25,
        "hunters_hall" => 1.25,
        "foragers_shed" => 1.25,
        _ => FIRE_DEFAULT_BUILDING_BASE_FLAMMABILITY,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
