const ALL_BACKYARD_GARDENS: &[BackyardGardenDef] = &[
    BACKYARD_ORCHARD,
    BACKYARD_APPLE_ORCHARD,
    BACKYARD_CHERRY_ORCHARD,
    BACKYARD_PEAR_ORCHARD,
    BACKYARD_ARONIA_ORCHARD,
    BACKYARD_ROSEHIP_ORCHARD,
    BACKYARD_VEGETABLE_GARDEN,
    BACKYARD_CABBAGE_GARDEN,
    BACKYARD_CARROT_GARDEN,
    BACKYARD_BEETROOT_GARDEN,
    BACKYARD_FLOWER_GARDEN,
    BACKYARD_HERB_GARDEN,
    BACKYARD_ANIMAL_PEN,
    BACKYARD_CHICKEN_PEN,
    BACKYARD_GOAT_PEN,
    BACKYARD_PIG_PEN,
    BACKYARD_BACKYARD_APIARY,
];

pub fn backyard_garden_def(kind: BackyardGardenKind) -> &'static BackyardGardenDef {
    ALL_BACKYARD_GARDENS
        .iter()
        .find(|def| def.kind == kind)
        .expect("missing backyard garden def")
}

pub fn backyard_garden_def_by_slug(slug: &str) -> Option<&'static BackyardGardenDef> {
    ALL_BACKYARD_GARDENS.iter().find(|def| def.slug == slug)
}

